import sys
from collections import deque

def min_days_to_pass_exams(n, m, d, a):
    # Create a list of available days for each exam
    exam_days = [[] for _ in range(m + 1)]
    for i in range(n):
        if d[i] > 0:
            exam_days[d[i]].append(i)

    # Check if it's possible to pass all exams
    for i in range(1, m + 1):
        if len(exam_days[i]) < a[i]:
            return -1

    # Initialize the queue for BFS
    queue = deque()
    for i in range(1, m + 1):
        queue.append((exam_days[i][a[i] - 1], i))

    # Initialize the visited set
    visited = set()
    for i in range(1, m + 1):
        visited.add((exam_days[i][a[i] - 1], i))

    # Perform BFS to find the minimum number of days
    while queue:
        current_day, current_exam = queue.popleft()

        # If we have covered all exams, return the current day
        if len(visited) == m:
            return current_day

        # Try to move to the next exam
        for next_exam in range(1, m + 1):
            if next_exam != current_exam:
                next_day = exam_days[next_exam][a[next_exam] - 1]
                if next_day > current_day and (next_day, next_exam) not in visited:
                    visited.add((next_day, next_exam))
                    queue.append((next_day, next_exam))

    return -1

# Read input
n, m = map(int, sys.stdin.readline().split())
d = list(map(int, sys.stdin.readline().split()))
a = list(map(int, sys.stdin.readline().split()))

# Output the result
print(min_days_to_pass_exams(n, m, d, a))
